    for cat, n in Counter(p["category"] for p in POSTS).items():
        print(" ", cat, n)
    ids = [p["id"] for p in POSTS]
    print("Уникальных id:", len(set(ids)))
    print("Дней при 3 постах в день:", round(len(POSTS) / 3))